const fs = require('fs');

const lines = fs.readFileSync(0, 'utf8').split(/\r?\n/);
const N = lines[0].trim();
const M = parseInt(lines[1], 10);

const digit = {
  a: '2', b: '2', c: '2',
  d: '3', e: '3', f: '3',
  g: '4', h: '4', i: '4',
  j: '5', k: '5', l: '5',
  m: '6', n: '6', o: '6',
  p: '7', q: '7', r: '7', s: '7',
  t: '8', u: '8', v: '8',
  w: '9', x: '9', y: '9', z: '9'
};

let answer = 0;

for (let i = 0; i < M; i++) {
  const word = lines[2 + i] || '';

  if (word.length !== N.length) continue;

  let ok = true;
  for (let j = 0; j < word.length; j++) {
    if (digit[word[j]] !== N[j]) {
      ok = false;
      break;
    }
  }

  if (ok) answer++;
}

console.log(answer);
